describe('ToolRegistry', () => {
  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('throws synchronously from register naming the tool when a static inputSchema is uncompilable', () => {
    const registry = new ToolRegistry();
    const malformedDefinition = {
      name: 'lookupOrder',
      description: 'Fetch an order',
      inputSchema: {type: 'object', required: 'orderId'},
    };

    expect(() => registry.register(malformedDefinition, async () => 'ok')).toThrow(/lookupOrder/);
  });

  it('caches compiled validators by schema reference for function-valued definitions across execute calls', async () => {
    let activeSchema: Record<string, unknown> = {type: 'object'};
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      () => ({name: 'dynamicLookup', description: 'Lookup by active field', inputSchema: activeSchema}),
      async () => 'ok'
    );

    const firstSchema = {type: 'object', required: ['alpha'], properties: {alpha: {type: 'string'}}};
    activeSchema = firstSchema;
    await registry.execute('dynamicLookup', {alpha: 'one'});
    await registry.execute('dynamicLookup', {alpha: 'two'});

    const secondSchema = {type: 'object', required: ['beta'], properties: {beta: {type: 'string'}}};
    activeSchema = secondSchema;
    await registry.execute('dynamicLookup', {beta: 'three'});
    await registry.execute('dynamicLookup', {beta: 'four'});

    const {calls} = compileSpy.mock;
    expect(calls.map(([schema]) => schema)).toEqual([firstSchema, secondSchema]);
  });
});

